import math
state={}
def control(o):
 b=o['local_map']['bay_corners']
 if o['phase']['index']==2:
  wake('Phase 2 reached; ready to drive out')
  return (0,0)
 dx=b[1][0]-b[0][0]; dy=b[1][1]-b[0][1]
 th=-math.atan2(dy,dx)
 c=math.cos(th); s=math.sin(th)
 x=9.6-(c*b[0][0]-s*b[0][1]); y=-14.8-(s*b[0][0]+c*b[0][1])
 # Smooth quarter circle into the side road.
 R=8.85; start=3.0
 if x<start and y>-1:
  along=x
 else:
  a=math.atan2(x-start,y+R)
  along=start+R*max(0,min(math.pi/2,a))
 if y < -R: along=start+R*math.pi/2+(-R-y)
 look=3.0; q=along+look
 if q<start: tx=q; ty=0
 elif q<start+R*math.pi/2:
  a=(q-start)/R; tx=start+R*math.sin(a); ty=-R+R*math.cos(a)
 else: tx=11.85; ty=-R-(q-start-R*math.pi/2)
 err=math.atan2(ty-y,tx-x)-th
 err=(err+math.pi)%(2*math.pi)-math.pi
 dist=max(1,math.hypot(tx-x,ty-y))
 k=2*math.sin(err)/dist
 ht=max(-38,min(38,math.degrees(math.atan(4.9*k))))
 h=o['hitch_deg']; hr=math.radians(h)
 eq=math.degrees(math.atan2(2.5*math.sin(hr),3.6+1.3*math.cos(hr)))
 steer=max(-45,min(45,eq+1.8*(h-ht)))
 if abs(h)>55:
  wake('Hitch angle needs correction')
  return (0,0)
 return (steer,-0.85)

